use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
        }
    }

    pub fn insert(&mut self, key: K, value: V) {
        self.entries.insert(key, value);
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }
}

