#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ParseError {
    MissingValue,
    InvalidArgument,
    OutOfRange,
}

pub fn parse_count_or_abort<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    match parse_count(args) {
        Ok(count) => count,
        Err(ParseError::MissingValue) => abort_with("std::logic_error", "basic_string::_S_construct null not valid"),
        Err(ParseError::InvalidArgument) => abort_with("std::invalid_argument", "stoi"),
        Err(ParseError::OutOfRange) => abort_with("std::out_of_range", "stoi"),
    }
}

pub fn parse_count<I>(args: I) -> Result<i32, ParseError>
where
    I: IntoIterator<Item = String>,
{
    let args: Vec<String> = args.into_iter().collect();
    let mut count = 1;

    if args.len() > 1 && args[1] == "--a" {
        let value = args.get(2).ok_or(ParseError::MissingValue)?;
        count = parse_stoi_like(value)?;
    }

    Ok(count)
}

fn parse_stoi_like(input: &str) -> Result<i32, ParseError> {
    let bytes = input.as_bytes();
    let mut index = 0;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let limit = if negative {
        i32::MAX as i64 + 1
    } else {
        i32::MAX as i64
    };

    let mut magnitude = 0_i64;
    let mut saw_digit = false;

    while index < bytes.len() {
        let byte = bytes[index];
        if !byte.is_ascii_digit() {
            break;
        }

        saw_digit = true;
        let digit = i64::from(byte - b'0');
        if magnitude > (limit - digit) / 10 {
            return Err(ParseError::OutOfRange);
        }

        magnitude = magnitude * 10 + digit;
        index += 1;
    }

    if !saw_digit {
        return Err(ParseError::InvalidArgument);
    }

    let signed_value = if negative { -magnitude } else { magnitude };
    Ok(signed_value as i32)
}

fn abort_with(exception: &str, message: &str) -> ! {
    eprintln!(
        "terminate called after throwing an instance of '{}'",
        exception
    );
    eprintln!("  what():  {}", message);
    std::process::abort();
}

